// app/docs/[[...slug]]/page.tsx (Optional Catch-all)
interface PageProps {
  params: Promise<{ slug?: string[] }>;
}

export default async function DocPage({ params }: PageProps) {
  const { slug } = await params; // Bắt buộc await trong Next.js 15+

