// app/api/revalidate/route.ts (Webhook Handler từ Headless CMS)
import { NextRequest, NextResponse } from 'next/server';
import { revalidateTag } from 'next/cache';

export async function POST(request: NextRequest) {
  const secret = request.nextUrl.searchParams.get('secret');
  if (secret !== process.env.CMS_WEBHOOK_SECRET) {
    return NextResponse.json({ message: 'Invalid token' }, { status: 401 });
  }

  const body = await request.json();
  const tag = body.tag || 'posts';

  // Xóa cache ngay lập tức cho tag này
  revalidateTag(tag);

  return NextResponse.json({ revalidated: true, now: Date.now() });
}

// lib/api.ts
export async function getProductCatalog() {
  const res = await fetch('https://api.internal/products', {
    // Tự động lưu trữ vào Data Cache và revalidate sau 1 giờ hoặc qua tag
    next: {
      revalidate: 3600,
      tags: ['catalog', 'products'],
    },
  });

  if (!res.ok) {
    throw new Error('Failed to fetch catalog');
  }
  return res.json();
}

