// app/actions/bookmark.ts
'use server';

import { revalidatePath } from 'next/cache';
import { db } from '@/lib/db';

export async function toggleBookmark(postId: string, isBookmarked: boolean) {
  // Chạy an toàn trên Server
  await db.bookmark.upsert({
    where: { postId },
    update: { active: isBookmarked },
    create: { postId, active: isBookmarked },
  });

  // Làm mới giao diện ngay lập tức
  revalidatePath('/posts');
  return { success: true };
}

