// app/actions/cart.ts
'use server';

import { revalidateTag } from 'next/cache';
import { db } from '@/lib/db';

export async function addToCartAction(productId: string) {
  await db.cartItem.create({ data: { productId, quantity: 1 } });

  // Xóa cache và re-render tất cả components gắn tag 'cart-data'
  revalidateTag('cart-data');

  return { success: true };
}

// app/actions/change-password.ts
'use server';
import { z } from 'zod';

const schema = z.object({ newPassword: z.string().min(8, 'Mật khẩu tối thiểu 8 ký tự') });

export async function changePasswordAction(prevState: any, formData: FormData) {
  const result = schema.safeParse({ newPassword: formData.get('password') });

  if (!result.success) {
    return { success: false, error: result.error.errors[0].message };
  }

  try {
    await db.user.updatePassword(result.data.newPassword);
    return { success: true, error: null };
  } catch (err) {
    // Lỗi hệ thống: log lại server-side và trả về lỗi thân thiện
    console.error('Database failure:', err);
    return { success: false, error: 'Hệ thống đang bảo trì, vui lòng thử lại sau.' };
  }
}

