// middleware.ts
import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

export function middleware(request: NextRequest) {
  const sessionToken = request.cookies.get('session_token')?.value;
  const { pathname } = request.nextUrl;

  // Chặn truy cập trang bảo vệ nếu chưa đăng nhập
  if (!sessionToken && pathname.startsWith('/dashboard')) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('from', pathname);
    return NextResponse.redirect(loginUrl);
  }

  return NextResponse.next();
}

export const config = {
  // Loại trừ file tĩnh và API không cần thiết
  matcher: ['/dashboard/:path*', '/admin/:path*'],
};

// app/actions/auth.ts (Ghi cookie trong Server Action)
'use server';
import { cookies } from 'next/headers';

export async function loginAction(token: string) {
  const cookieStore = await cookies();
  cookieStore.set('session', token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
  });
}

// app/profile/page.tsx (Chỉ đọc cookie trong Server Component)
import { cookies } from 'next/headers';

export default async function ProfilePage() {
  const cookieStore = await cookies();
  const session = cookieStore.get('session')?.value;
  return <div>Session: {session}</div>;
}

